#include "svg_plot.h"
#include <stdio.h>
#include <float.h>
#include <math.h>
SvgOptions svg_default_options(void){return (SvgOptions){900,700,50,true};}
int write_svg_file(const char*path,const SimulationResult*s,const EstimateSample*e,size_t en,const SvgOptions*op){if(!path||!s||!s->truth_count)return -1;SvgOptions o=op?*op:svg_default_options();double minx=DBL_MAX,miny=DBL_MAX,maxx=-DBL_MAX,maxy=-DBL_MAX;for(size_t i=0;i<s->truth_count;i++){Point2D p=s->truth[i].pos;if(p.x<minx)minx=p.x;if(p.x>maxx)maxx=p.x;if(p.y<miny)miny=p.y;if(p.y>maxy)maxy=p.y;}double rx=fmax(maxx-minx,1),ry=fmax(maxy-miny,1),scale=fmin((o.width-2.0*o.margin)/rx,(o.height-2.0*o.margin)/ry),ox=o.margin,oy=o.margin;FILE*f=fopen(path,"w");if(!f)return -1;fprintf(f,"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"%d\" height=\"%d\"><rect width=\"100%%\" height=\"100%%\" fill=\"white\"/><polyline fill=\"none\" stroke=\"#444\" points=\"",o.width,o.height);for(size_t i=0;i<s->truth_count;i++){Point2D p=s->truth[i].pos;fprintf(f,"%.1f,%.1f ",ox+(p.x-minx)*scale,o.height-(oy+(p.y-miny)*scale));}fprintf(f,"\"/>");if(o.show_gps)for(size_t i=0;i<s->gps_count;i++)if(s->gps[i].valid){Point2D p=s->gps[i].pos;fprintf(f,"<circle cx=\"%.1f\" cy=\"%.1f\" r=\"2\" fill=\"#d33\"/>",ox+(p.x-minx)*scale,o.height-(oy+(p.y-miny)*scale));}fprintf(f,"<polyline fill=\"none\" stroke=\"#1971c2\" stroke-width=\"2\" points=\"");for(size_t i=0;i<en;i++){Point2D p=e[i].pos;fprintf(f,"%.1f,%.1f ",ox+(p.x-minx)*scale,o.height-(oy+(p.y-miny)*scale));}fprintf(f,"\"/><text x=\"20\" y=\"30\" font-family=\"sans-serif\">GPS + Kalman filter (simulated)</text></svg>\n");int bad=ferror(f);fclose(f);return bad?-1:0;}
